# Safe access
d = {'name': 'Alice', 'age': 30}
print(d.get('email'))             # None — no KeyError
print(d.get('email', 'unknown'))  # 'unknown'

# Building a grouping dict
from collections import defaultdict
words = ['apple', 'ant', 'banana', 'bear', 'cherry']
by_letter = defaultdict(list)
for word in words:
    by_letter[word[0]].append(word)
# {'a': ['apple', 'ant'], 'b': ['banana', 'bear'], 'c': ['cherry']}

# Without defaultdict — using setdefault
by_letter2 = {}
for word in words:
    by_letter2.setdefault(word[0], []).append(word)

# Merging (Python 3.9+)
defaults = {'timeout': 30, 'retries': 3}
overrides = {'timeout': 10}
config = defaults | overrides  # {'timeout': 10, 'retries': 3}

# Pre-3.9
config = {**defaults, **overrides}

# Iterating
for key, value in d.items():
    print(f'{key}: {value}')

# pop with default
value = d.pop('missing_key', 'fallback')  # no KeyError

# Invert a dict (values must be unique)
original = {'a': 1, 'b': 2, 'c': 3}
inverted = {v: k for k, v in original.items()}
# {1: 'a', 2: 'b', 3: 'c'}

# Filter — keep only high scores
scores = {'alice': 85, 'bob': 42, 'carol': 91}
passing = {name: score for name, score in scores.items() if score >= 60}
# {'alice': 85, 'carol': 91}

# Transform values
upper_scores = {name.upper(): score for name, score in scores.items()}

# Flatten a matrix
matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
flat = [cell for row in matrix for cell in row]
# [1, 2, 3, 4, 5, 6, 7, 8, 9]

# Set comprehension — unique first characters
words = ['apple', 'ant', 'banana', 'bear']
first_letters = {w[0] for w in words}  # {'a', 'b'}

# Conditional expression in comprehension (ternary)
result = [x if x > 0 else -x for x in [-3, 1, -2, 4]]  # abs()
# [3, 1, 2, 4]
